import type { DataSourceSettings } from '@grafana/data';
import { getBackendSrv } from '@grafana/runtime';
import { SUPPORTED_DATASOURCE_TYPES, type SupportedDataSourceType } from '../constants';
import { DATASOURCE_NAME_PREFIX, HIDE_ERROR_ALERT, SHOW_ERROR_ALERT } from './constants';

export type SupportedDataSourceSettings = DataSourceSettings & { type: SupportedDataSourceType };

/** returns a list of existing data sources, supported by 3CX dashboards */
export function getSupportedDataSources(): Promise<SupportedDataSourceSettings[]> {
  return getBackendSrv()
    .get<DataSourceSettings[]>('/api/datasources', undefined, undefined, SHOW_ERROR_ALERT)
    .then((dataSources) => dataSources.filter(isSupportedDataSource))
    .catch(() => []);
}

/** creates a new data source for a given type */
export function createDataSource(dataSourceType: SupportedDataSourceType): Promise<SupportedDataSourceSettings> {
  return getBackendSrv()
    .post<{ datasource: SupportedDataSourceSettings }>(
      '/api/datasources',
      { access: 'proxy', type: dataSourceType, name: DATASOURCE_NAME_PREFIX + dataSourceType.replace('grafana-', '') },
      SHOW_ERROR_ALERT
    )
    .then(({ datasource }) => datasource);
}

export type DataSourceHealthStatus = 'OK' | 'Missing' | 'Unhealthy';

export function getDataSourceHealth(dataSourceUid: string): Promise<DataSourceHealthStatus> {
  const backend = getBackendSrv();
  const dataSourceUrl = `/api/datasources/uid/${dataSourceUid}`;

  // surprisingly, health request gives error 500 instead of 404 in case of a missing data source;
  // so we check data source existence by requesting the data source directly (gives 404)
  // checking the error message is not a stable solution
  return backend
    .get(dataSourceUrl, undefined, undefined, HIDE_ERROR_ALERT)
    .then(() => backend.get(`${dataSourceUrl}/health`, undefined, undefined, HIDE_ERROR_ALERT))
    .then<DataSourceHealthStatus>(() => 'OK' satisfies DataSourceHealthStatus)
    .catch(error => error.status === 404 ? 'Missing' : 'Unhealthy');
}

function isSupportedDataSource(dataSource: DataSourceSettings): dataSource is SupportedDataSourceSettings {
  return (SUPPORTED_DATASOURCE_TYPES as readonly string[]).includes(dataSource.type);
}
