import React, { useCallback, useEffect, useState } from 'react';
import { TCXPluginMeta } from '../types';
import { DashboardMeta, getDashboards } from '../api/dashboards';
import { getDataSourceHealth, DataSourceHealthStatus } from '../api/data-sources';
import { PluginPage, useReturnToPrevious } from '@grafana/runtime';
import { Alert, Icon, LoadingPlaceholder, Stack, TextLink } from '@grafana/ui';
import { useTranslation, Trans } from 'react-i18next';
import { CONFIGURATION_ROUTE, dashboardPage, dataSourceEditPage } from '../routes';

// MainPage shows one of two states:
// - startup (no configuration): shows a startup guide which leads to the configuration page
// - after previously done configuration: shows data source health status and the list of published dashboards
const MainPage: React.FC<TCXPluginMeta> = (props) => {
  const { t } = useTranslation();
  const { jsonData, name } = props;
  const dataSource = jsonData?.dataSource;
  const [availableDashboards, setAvailableDashboards] = useState<DashboardMeta[] | null>(null);
  const [dataSourceStatus, setDataSourceStatus] = useState<DataSourceHealthStatus | 'None' | undefined>(undefined);
  const setReturnToPrevious = useReturnToPrevious();

  const onDataSourceLinkClick = useCallback(() => setReturnToPrevious(name), [setReturnToPrevious, name]);

  useEffect(() => {
    if (!dataSource) {
      // show startup state
      setDataSourceStatus('None');
      setAvailableDashboards([]);
      return;
    }

    getDataSourceHealth(dataSource.uid).then(setDataSourceStatus);

    // dashboards exist even without datasource, though they show only errors
    getDashboards().then((dashboards) => {
      setAvailableDashboards(dashboards.sort((d1, d2) => d1.title.localeCompare(d2.title)));
    });
  }, [dataSource]);

  return (
    <PluginPage>
      {dataSourceStatus === 'OK' && (
        <p>
          <Icon name="check-circle" color="green" /> <Trans>Data source is connected and healthy</Trans>.
        </p>
      )}
      {dataSourceStatus === 'Missing' && (
        <Alert severity="warning" title={t('Configured data source is missing.')} style={{ display: 'inline-block' }}>
          <Trans>
            Please select data source in <TextLink href={CONFIGURATION_ROUTE}>Configuration</TextLink> to ensure
            monitoring dashboards work correctly.
          </Trans>
        </Alert>
      )}
      {dataSource && dataSourceStatus === 'Unhealthy' && (
        <Alert
          severity="warning"
          title={t('Unable to connect to the selected data source.')}
          style={{ display: 'inline-block' }}
        >
          <Trans>
          Please review and test your data source connection in{' '}
          <TextLink href={dataSourceEditPage(dataSource)} onClick={onDataSourceLinkClick}>
            Data Source Settings
          </TextLink>{' '}
          to ensure monitoring dashboards work correctly.
          </Trans>
        </Alert>
      )}
      {dataSourceStatus && availableDashboards ? (
        availableDashboards.length > 0 ? (
          <>
            <p><Trans>Below you can find the available dashboards</Trans>:</p>
            <Stack direction="column" gap={1}>
              {availableDashboards.map((dashboard) => (
                <TextLink key={dashboard.uid} href={dashboardPage(dashboard)} inline={false}>
                  {dashboard.title}
                </TextLink>
              ))}
            </Stack>
          </>
        ) : (
          <p>
            <Trans>
            Begin with connecting data source and publishing dashboards in{' '}
            <TextLink href={CONFIGURATION_ROUTE}>Configuration</TextLink>.
            </Trans>
          </p>
        )
      ) : (
        <LoadingPlaceholder text="" />
      )}
    </PluginPage>
  );
};

export default MainPage;
