export const DS_POSTRGESQL = 'grafana-postgresql-datasource';
export const DS_BIGQUERY = 'grafana-bigquery-datasource';
export const DS_MYSQL = 'mysql';
export const DS_MSSQL = 'mssql';

export const SUPPORTED_DATASOURCE_TYPES = [
  DS_POSTRGESQL,
  DS_BIGQUERY,
  DS_MYSQL,
  DS_MSSQL,
] as const;

export type SupportedDataSourceType = typeof SUPPORTED_DATASOURCE_TYPES[number];

export const DATASOURCE_TYPE_LABEL: Record<SupportedDataSourceType, string> = {
  [DS_POSTRGESQL]: 'Postgre SQL',
  [DS_BIGQUERY]: 'BigQuery',
  [DS_MYSQL]: 'MySQL',
  [DS_MSSQL]: 'Microsoft SQL',
};
